If $M$ is an $R$-module, the \emph{Frobenius functor} is a right exact functor in both the categories of right and left $R$-modules, defined by:

\begin{center}
$F(M) := R^{\frac{1}{f}} \otimes_R M$
\end{center}

\noindent and if $\varphi : M \rightarrow N$ is an $R$-module map, then $F(\varphi) : F(M)\rightarrow F(N)$ is the map:

\begin{center}
$F(\varphi) := 1_{R^{1/f}} \otimes_R \varphi$
\end{center}

\label{rmk:Zero}
\indent Note that since we are discussing a directed system, by definition $0 \in (R^\infty \otimes_R M)$ is precisely the image of the elements of $0^F_{F^e(M)}$ as $e$ varies, or $\underrightarrow{\lim} \ 0^F_{F^e(M)} = 0 \in R^\infty \otimes_R M$.  That is,

\begin{align*}
m_{e} \in 0^F_{F^e(M)} \ \text{for some} \ e & \Leftrightarrow m_{e'} = 0 \in F^{e'}(M) \ \text{for some} \ e \leq e' \\
& \Leftrightarrow m_{\infty} = 0 \ \text{in} \ R^\infty
\end{align*}

\label{rmk:fseqfacts}
Let $S$ be a ring of characteristic $p > 0$, and let $\lbrace J_e \rbrace$ be an $f$-sequence in $S$.
\begin{enumerate}
\item For all $e$, $\operatorname{Ass}_S(S/J_e) \subseteq $ $\operatorname{Ass}_S(S/J_{e + 1})$ \cite[Remark $4.2, \ iv)$]{NoSh.alpha}.
\item  For all $e$, $J_e$ is Frobenius closed \cite[Remark $4.1 \ ii)$]{NoSh.alpha}.  Hence given an ideal $I \subset S$ we can view $\lbrace (I^{[q]})^F \rbrace$ as a minimal $f$-sequence, since any $f$-sequence which contians $I$ at some stage must therefore contain the entire sequence. 
\item $\sqrt{J_e} = \sqrt{J_{e'}}$ for all $e, e'$, or all ideals in the sequence have the same radical \cite[Remark $4.2, i)$]{NoSh.alpha}.
\item  For a Notherian ring $R$ there exists a bijective correspondence between $f$-sequences of $R$ and ideals in $R^\infty$ \cite[Corollary $3.2$]{NoSh.alpha}.  For an ideal $J \subset R^\infty$, this correspondence is given explicitly by $\Gamma \ : \ J \mapsto \lbrace J_e \rbrace$, where for every $e \in \mathbb{N}$, $J_e := \lbrace r \in R \ | \ r^{\frac{1}{q}} \in J \rbrace$.  Alternatively, we can say $J_e = f^e(J) \cap R$, and in particular note that $J_0 = J \cap R$.
\end{enumerate}

Let $R$ be a reduced Noetherian ring of characteristic $p > 0$, and Let $\lbrace J_e \rbrace_{e \in \mathbb{N}}$ be an $f$ sequence in $R$, and let let $\mathfrak{a} = \sqrt{J_e}$ for all $e$.  Let $J \subset R$ be the ideal such that the ascending chain

\begin{center}
$\ldots \supseteq J_{e-2} \supseteq J_{e - 1} \supseteq J_{e} \supset \ldots$
\end{center}

\noindent stabilizes, for $e \in \mathbb{N}$.  Then $J = \mathfrak{a}$.

\label{rmk:Fseqfacts}
Let $R$ be a Noetherian ring of characteristic $p > 0$, and let $\lbrace N_e \rbrace$ be an $f$-sequence in $F^e(M)$.
\begin{enumerate}
\item For all $e$, $\operatorname{Ass}_R \big( F^e(M)/N_e \big) \subseteq $ $\operatorname{Ass}_R \big( F^{e+1}(M)/N_{e+1} \big)$.

\begin{proof}
\indent Let $P \in \operatorname{Ass}_R \big( F^e(M)/N_e \big)$ with $P = (N_e :_R m_{e})$, where $g_{e}(m_{e}) = m_{e+1}  \notin N_{e+1}$ by definition of an $F$-sequence.  For $r \in P$, $g_{e}(r \circ m_{e}) = g_{e}(r^\frac{1}{q} m_{e}) = r^\frac{1}{q} m_{e+1} = r^\frac{pq}{q} \circ m_{e+1} = r^p \circ m_{e+1} \in N_{e+1}$.  Hence $P^{[p]} \subseteq (N_{e+1} :_R m_{e+1})$. 

\indent On the other hand, if $s \in (N_{e+1} :_R m_{e+1})$, then certainly $s^p \in (N_{e+1} :_R m_{e+1})$.  We then have $g_{e}^{-1}(s^p \ \circ \ m_{e+1}) = g_{e}^{-1}(s^\frac{p}{qp} m_{e+1}) = g_{e}^{-1}(s^\frac{1}{q} m_{e+1}) = s^\frac{1}{q} m_{e} = s \circ m_{e} \in N_e$, again by definition of $F$-sequences, and $s \in P$.

\indent Finally, since $P^{[p]} \subseteq (N_{e+1} :_R m_{e+1}) \subseteq P$, and $P = \sqrt{P^{[p]}}$, $P$ is minimal over $P^{[p]}$, and hence $P$ is minimal over the annihilator of an element of $F^{e+1}(M)/N_{e+1}$, and since $R$ is Noetherian (see sec.~\ref{sec:GenAss}), $P \in \operatorname{\widetilde{Ass}}_R \big( F^{e+1}(M)/  N_{e+1} \big) = \operatorname{Ass}_R \big( F^{e+1}(M)/N_{e+1} \big)$.
\end{proof}

\item  For every $e$, $N_e$ is Frobenius closed.

\begin{proof}
\indent Let $N_e$ be a term in an $F$-sequence, and fix $n_{e} \in N_e^F$.  Then $g_{e,e'}(n_e) = n_{e'} \in N^{[q']} \subseteq N_{e'}$ for $e' \gg e$.  But then $n_e \in g_{e,e'}^{-1}(n_{e'})$, whereby $n_e \in g_{e,e'}^{-1}(N_{e'}) = N_e$.
\end{proof}

\item $\sqrt{\operatorname{ann}_R \big( F^e(M)/N_e \big)} = \sqrt{\operatorname{ann}_R \big( F^{e'}(M)/N_{e'} \big)}$ for all $e, e'$.

\begin{proof}
By lemma~\ref{lem:fseqann}, $\lbrace J_e \rbrace = \lbrace \operatorname{ann}_R \big( F^e(M)/N_e \big) \rbrace$ is an $f$-sequence.  Then this statement is true by remark~\ref{rmk:fseqfacts}, fact $3$.
\end{proof}

\item  There exists a bijective correspondence between $F$-sequences of $F^e(M)$ and submodules of $R^\infty \otimes_R M$.  This fact is true because any sub-module of $N \subseteq R^\infty \otimes_R M$ is by definition the direct limit of an $F$-sequence of modules.

\indent For an submodule $N \subseteq R^\infty \otimes_R M$, this correspondence is given explicitly by $\Gamma \ : \ N \mapsto \lbrace N_e \rbrace$, where for every $e \in \mathbb{N}$, $N_e := \lbrace n_{e} \in F^e(M) \ | \ n_{\infty} \in N \rbrace$. 
\end{enumerate}

\label{example:Fseqs} \hspace{1 cm}
\begin{enumerate}
\item Recall the $f$-sequence of ideals $\lbrace J_e \rbrace = \lbrace (I^{[q]})^F \rbrace$ for some ideal $I$.  Here $N_e = (R^{\frac{1}{f^e}} \otimes_R I)^F \cong (IR^{\frac{1}{p^e}})^F$, where this last expression is isomorphic to $(I^{[q]})^F \subseteq R$.  Notice that $N = \underrightarrow{\lim} \ N_e \cong IR^\infty$, which as we stated above was the ideal in $R^\infty$ corresponding to this $f$-sequence of ideals.
\item For $R =  k[x,y]$, recall the $f$-sequence of ideals $\lbrace J_e \rbrace = \lbrace (x, y^q) \rbrace$.  Here $N_e \cong (x^{\frac{1}{q}},y)R^{\frac{1}{q}}$, which is isomorphic to $(x,y^q) \subseteq R$.  Notice that $N = \underrightarrow{\lim} \ N_e \cong (x, x^{\frac{1}{p}}, x^{\frac{1}{p^2}}, \ldots, y) R^\infty$, which again was the ideal in $R^\infty$ corresponding to this $f$-sequence of ideals. 
\item Letting $R$ and $M$ be as above, then $\lbrace 0^F_{F^e(M)} \rbrace$ is an $F$-sequence of sub-modules of $F^e(M)$.  This fact is easy to see because:
\begin{align*}
m_e \in 0^F_{F^e(M)} &\Leftrightarrow g_{e,e'}(m_e) = 0 \in F^{e'}(M) \ \text{for} \ e' \gg e \\
&\Leftrightarrow g_{e}(m_{e}) \in 0^F_{F^{e+1}(M)}
\end{align*}
As stated above in remark~\ref{rmk:Zero}, $N = 0 = \underrightarrow{\lim} \ 0^F_{F^e(M)}$.
\end{enumerate}

Let $R = \mathbb{F}_p [x]$, and hence $R^\infty  = \mathbb{F}_p [x, x^{\frac{1}{p}}, x^{\frac{1}{p^2}}, \ldots]$.  We claim $\operatorname{Ass}_{R^\infty}(R^\infty / (x) R^\infty) = \emptyset$.  

\indent To show this claim, first note that $(x)^\infty = \sqrt{(x) R^\infty}$.  Since $(x)^\infty$ is maximal it is therefore the only prime ideal which contains $(x)R^\infty$, and hence is the only possible element of $\operatorname{Ass}_{R^\infty}(R^\infty / (x) R^\infty)$.

\indent Suppose $(x)^\infty = ((x) R^\infty :_{R^\infty} r)$ for some $r \in R^\infty \setminus (x)R^\infty$,  where $r = \Sigma_{i = 0}^{n} a_i x^{\frac{i}{q}}$ for some $q$, and $a_i \in \mathbb{F}_p$ for all $i$.  Then $x^{\frac{1}{pq}}r \notin (x) R^\infty$.  We can see this fact by multiplying: 

\begin{align*}
x^{\frac{1}{pq}} r & = x^{\frac{1}{pq}} \Sigma_{i = 0}^{n} a_i x^{\frac{i}{q}} \\
& = \Sigma_{i = 0}^{n} a_i x^{\frac{1}{pq}} x^{\frac{i}{q}} \\
& = \Sigma_{i = 0}^{n} a_i x^{\frac{ip + 1}{qp}}
\end{align*}

\noindent But since $r \notin (x)R^\infty$, for at least one $i$, the corresponding monomial is non-zero, and $i < q$.  But then $\frac{ip + 1}{qp} < 1$, and we see that $x^{\frac{1}{pq}} r \notin (x)R^\infty$.  

\indent Hence $(x)^\infty$ cannot be an associated prime of $R^\infty / (x) R^\infty$, and thus \\ $\operatorname{Ass}_{R^\infty}(R^\infty / (x) R^\infty) = \emptyset$.

Let $S$ be any commutative ring with identity, let $M$ be an $S$-module, and let $I\subset S$ be an ideal such that $M \neq IM$.
\begin{enumerate}
\item $\operatorname{c \ gr}_S (I,M) := \text{sup} \lbrace | \mathbf{x} | \rbrace$ where $\mathbf{x} \subset I$ is a finite $M$-regular sequence contained in $I$.
\item $\operatorname{k \ gr}_S (I,M) := \text{sup} \lbrace n - h \rbrace$ where $\mathbf{x} = x_1, \ldots, x_n \subset I$ is a finite set, and $h$ is index of the highest non-zero homology group of the Koszul complex $K_\bullet (x_1, \ldots, x_n ; M)$.  If $\mathbf{x}$ is a finite sequence, we can discuss the koszul grade on $\mathbf{x}$, $\operatorname{k \ gr}_S (\mathbf{x},M) := n - h$ with $n$ and $h$ as above.
\item $\operatorname{r \ gr}_S (I,M) := \text{inf} \lbrace i \ | \ \operatorname{Ext}^i_S (S/I, M) \neq 0 \rbrace$.
\end{enumerate}

\label{rmk:AssDepth}
Let $(S, \mathfrak{n}, l)$ be a local ring with quotient field $l = S/\mathfrak{n}$, and let $M$ be an $S$-module such that $M \neq \mathfrak{n} M$. Then,
\begin{enumerate}
\item $\mathfrak{n} \in \operatorname{Ass}_S (M) \ \text{if and only if} \ \operatorname{r \ depth}_S (M) = 0$
\item $\mathfrak{n} \in \operatorname{sK}_S (M) \ \text{if and only if} \ \operatorname{k \ depth}_S (M) = 0$
\item $\mathfrak{n} \in \operatorname{K}_S (M) \ \text{if and only if} \ \operatorname{c \ depth}_S (M) = 0$
\end{enumerate}

\indent \underline{1):} 
$$\begin{array}{ll}
\mathfrak{n} \in \operatorname{Ass}_S (M) & \Leftrightarrow 0 \neq \operatorname{Hom}_S(l,M) \cong \operatorname{Ext}_S^0(l,M) \\
& \Leftrightarrow \operatorname{r \ depth}_S (M) = 0
\end{array}$$
\indent \underline{2):} 
$$\begin{array}{ll}
\mathfrak{n} \in \operatorname{sK}_S (M) & \Leftrightarrow \text{for all finite} \ \mathbf{x} = x_1, \ldots, x_n \subset \mathfrak{n}, (\mathbf{x}) \subseteq \text{ann}_S(m) \subseteq \mathfrak{n} \\
& \ \ \ \ \text{for some non-zero} \ m \in M \\
& \Leftrightarrow \ \text{for all finite} \ \mathbf{x} = x_1, \ldots, x_n \subset \mathfrak{n}, H_n(\mathbf{x};M) \neq 0 \\
& \Leftrightarrow \text{sup} \lbrace \operatorname{k \ gr}_S(\mathbf{x};M) \ | \ \mathbf{x} \subset \mathfrak{n} \ \text{is a finite set} \rbrace = 0 \\
& \Leftrightarrow \operatorname{k \ depth}_S(M) = 0
\end{array}$$
\indent \underline{3):}
$$\begin{array}{ll}
\mathfrak{n} \in \operatorname{K}_S (M) & \Leftrightarrow \text{for all} \ x \in \mathfrak{n}, \ x \in \text{ann}_S(m) \subseteq \mathfrak{n} \ \text{for some} \ m \in M, \ \text{i.e.,} \\
& \ \ \ \ \text{there exist no} \ M$-$\text{regular elements in} \ \mathfrak{n} \\
& \Leftrightarrow \text{sup} \lbrace |\mathbf{x}| \ | \ \mathbf{x} \subset \mathfrak{n} \ \text{is a regular sequence} \rbrace = 0 \\
& \Leftrightarrow \operatorname{c \ depth}_S(M) = 0 \\
\end{array}$$

\label{rmk:Fp-Fcl}
If $R$ is an $F$-pure ring, then every ideal $I \subset R$ is Frobenius closed, since if $r^q \in I^{[q]}$, then $r \in IR^{\frac{1}{q}}$, and hence $\overline{r} = \overline{0}$ in $R^{\frac{1}{q}} / IR^{\frac{1}{q}} \cong (R^{\frac{1}{q}} \otimes_R R / I)$.  But since $R$ is $F$-pure, $R/I \cong (R \otimes_R R / I) \rightarrow (R^{\frac{1}{q}} \otimes_R R / I)$ is injective, $\overline{r} = \overline{0}$ in $R/I$, and $r \in I$. 

\indent In particular all $F$-pure rings are reduced, since the $0$ ideal is Frobenius closed.  Hence we need not mention the reduced assumption in section~\ref{sec:F-pureResults}.

\label{thm:Fseqweakass}
Let $R$ be a reduced Noetherian ring of characteristic $p > 0$, and let $R^\infty$ be its perfect closure.  Let $P$ and $P^\infty$ be corresponding prime ideals in $\operatorname{Spec}(R)$ and $\operatorname{Spec}(R^\infty)$ respectively.  Let $\lbrace N_e \rbrace \subseteq \lbrace F^e(M) \rbrace$ be an $F$-sequence of sub-modules of $F^e(M)$ for an $R$-module $M$.  Let $N = \underrightarrow{\lim} \ N_e$ be the corresponding sub-module of $(R^\infty \otimes_R M)$.  Then the following are all equivalent:  
\begin{enumerate}
\item $P \in \bigcup \operatorname{Ass}_R \big( F^e(M) / N_e \big)$ 
\item $P^\infty \in \operatorname{\widetilde{Ass}}_{R^\infty} \big( (R^\infty \otimes_R M)/N \big)$
\item $P^\infty \in \operatorname{sK}_{R^\infty} \big( (R^\infty \otimes_R M)/N \big)$
\end{enumerate}

\label{cor:WeakAss}
Let $R$ be a reduced Noetherian ring of characteristic $p > 0$, and let $R^\infty$ be its perfect closure.  Let $P$ and $P^\infty$ be corresponding prime ideals in $\operatorname{Spec}(R)$ and $\operatorname{Spec}(R^\infty)$ respectively.  Let $M$ be an $R$-module.  Then the following are all equivalent:  
\begin{enumerate}
\item $P \in \bigcup \operatorname{Ass}_R \big( F^e(M) / 0^F_{F^e(M)} \big)$
\item $P^\infty \in \operatorname{\widetilde{Ass}}_{R^\infty}(R^{\infty} \otimes_R M)$
\item $P^\infty \in \operatorname{sK}_{R^\infty}(R^{\infty} \otimes_R M)$
\end{enumerate}

\label{thm:CycModAssocPr}
Let $R$ be a reduced Noetherian ring of characteristic $p > 0$, and let $R^\infty$ be its perfect closure.  Let  $\lbrace J_e \rbrace$ be an $f$-sequence in $R$, and let $J \subset R^\infty$ be its corresponding ideal in $R^\infty$. Let $P$ and $P^\infty$ be corresponding prime ideals in $\operatorname{Spec}(R)$ and $\operatorname{Spec}(R^\infty)$ respectively.  Then the following are all equivalent:  

\begin{enumerate}
\item $P \in \bigcup \operatorname{Ass}_R (R / J_e)$
\item $P^\infty \in \operatorname{\widetilde{Ass}}_{R^\infty}(R^{\infty} / J)$
\item $P^\infty \in \operatorname{sK}_{R^\infty}(R^{\infty} / J$)
\end{enumerate}

Let $R$ be a reduced Noetherian ring of characteristic $p > 0$, let $I \subset R$ be an ideal, and let $R^\infty$ be its perfect closure.  Let $P$ and $P^\infty$ be corresponding prime ideals in $\operatorname{Spec}(R)$ and $\operatorname{Spec}(R^\infty)$ respectively.  Then the following are all equivalent:  
\begin{enumerate}
\item $P \in \bigcup \operatorname{Ass}_R (R / (I^{[q]})^F)$
\item $P^\infty \in \operatorname{\widetilde{Ass}}_{R^\infty}(R^{\infty} / I R^{\infty})$
\item $P^\infty \in \operatorname{sK}_{R^\infty}(R^{\infty} / I R^{\infty})$
\end{enumerate}

Let $(R, \mathfrak{m})$ be a local Noetherian $F$-pure ring of characteristic $p > 0$, and let $M$ be a finitely generated $R$-module.  Then,

\begin{center}
 $\operatorname{depth}_R (M) \geq \operatorname{depth}_R \big( F(M) \big)$.
\end{center}

Let $(R,\mathfrak{m})$ be an F-pure Noetherian local ring of characteristic $p > 0$, and let $M$ be a finitely generated $R$-module.  The \emph{stabilizing depth} is defined:

\begin{center}
$\operatorname{s \ depth}_R (M) := \operatorname{depth}_R \big( F^e(M) \big) \ \text{for } \ e \gg 0$.
\end{center}

Let $R$ be an $F$-pure Noetherian ring of characteristic $p > 0$, let $R^\infty$ be its perfect closure, and let $M$ be a finitely generated $R$-module.  Then $\operatorname{c \ depth}_{R^\infty} (R^\infty \otimes_R M)$ is finite, and more specifically

\begin{center}
$\operatorname{s \ depth}_R (M) \geq \operatorname{c \ depth}_{R^\infty} (R^\infty \otimes_R M)$
\end{center}

\label{lem:supkosz}
Let $(R,\mathfrak{m})$ be an F-pure Noetherian local ring of characteristic $p > 0$, let $(R^\infty, \mathfrak{m}^\infty)$ be its perfect closure, and let $M$ be a finitely generated $R$-module.  Then,

\begin{center}
$\operatorname{k \ depth}_{R^\infty} (R^\infty \otimes_R M) = \ \sup \lbrace \operatorname{k \ gr}_{R^\infty} \big(\mathfrak{m}^{[\frac{1}{q}]}R^\infty, (R^\infty \otimes_R M) \big) \rbrace$ for all $e \in \mathbb{N}$.
\end{center}

Let $(R,\mathfrak{m})$ be an F-pure Noetherian local ring of characteristic $p > 0$, let $R^\infty$ be its perfect closure, and let $M$ be a finitely generated $R$-module.  Then $\operatorname{k \ depth}_{R^\infty} (R^\infty \otimes_R M)$ is finite, and more specifically

\begin{center}
$\operatorname{k \ depth}_{R^\infty} (R^\infty \otimes_R M) = \operatorname{s \ depth}_R (M)$
\end{center}

\label{thm:twohyps}
 Let $(R,\mathfrak{m})$ be an F-pure Noetherian local ring of characteristic $p > 0$, and let $M$ be a finitely generated $R$-module.  If either of the following two conditions hold:

\begin{enumerate}
\item $R$ satisfies countable prime avoidance
\item $\displaystyle \bigcup \bigcup_{e} \operatorname{Ass}_R \big( F^e(M) / F^e(M) \mathbf{y} \big)$ contains finitely many prime ideals, where $\bf y$ $\subset R$ is a maximal $(R^\infty \otimes_R M)$ sequence in $R^\infty$
\end{enumerate}

then,

\begin{center}
$\operatorname{s \ depth}_R (M) = \operatorname{c \ depth}_{R^\infty} (R^\infty \otimes_R M)$
\end{center}
